// Package surcharge holds data access for per-lane surcharge overrides.
//
// The SQL matches db/queries/surcharge_overrides.sql so the queries can be
// moved to sqlc-generated code without changing behavior.
package surcharge

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// ErrNotFound is returned when no override exists for the requested lane.
var ErrNotFound = errors.New("surcharge override not found")

// Override is one row of surcharge_overrides.
type Override struct {
	ID        int64
	Lane      string
	RateBps   int32
	Active    bool
	CreatedAt time.Time
	UpdatedAt time.Time
}

// CreateParams are the caller-supplied fields for a new override.
type CreateParams struct {
	Lane    string
	RateBps int32
	Active  bool
}

// Store is the data-access handle for surcharge_overrides.
type Store struct {
	db *pgxpool.Pool
}

// NewStore returns a Store backed by db.
func NewStore(db *pgxpool.Pool) *Store {
	return &Store{db: db}
}

const createSQL = `
INSERT INTO surcharge_overrides (lane, rate_bps, active)
VALUES ($1, $2, $3)
RETURNING id, lane, rate_bps, active, created_at, updated_at`

const getByLaneSQL = `
SELECT id, lane, rate_bps, active, created_at, updated_at
FROM surcharge_overrides
WHERE lane = $1`

const listActiveSQL = `
SELECT id, lane, rate_bps, active, created_at, updated_at
FROM surcharge_overrides
WHERE active
ORDER BY lane`

// Create inserts a new override. It returns an error if the lane already has one
// (unique constraint on lane).
func (s *Store) Create(ctx context.Context, p CreateParams) (Override, error) {
	o, err := scanOverride(s.db.QueryRow(ctx, createSQL, p.Lane, p.RateBps, p.Active))
	if err != nil {
		return Override{}, fmt.Errorf("create surcharge override for lane %q: %w", p.Lane, err)
	}
	return o, nil
}

// GetByLane returns the override for lane, or ErrNotFound.
func (s *Store) GetByLane(ctx context.Context, lane string) (Override, error) {
	o, err := scanOverride(s.db.QueryRow(ctx, getByLaneSQL, lane))
	if errors.Is(err, pgx.ErrNoRows) {
		return Override{}, ErrNotFound
	}
	if err != nil {
		return Override{}, fmt.Errorf("get surcharge override for lane %q: %w", lane, err)
	}
	return o, nil
}

// ListActive returns every override with active = true, ordered by lane.
// It returns an empty slice, not nil, when there are none.
func (s *Store) ListActive(ctx context.Context) ([]Override, error) {
	rows, err := s.db.Query(ctx, listActiveSQL)
	if err != nil {
		return nil, fmt.Errorf("list active surcharge overrides: %w", err)
	}
	defer rows.Close()

	out := []Override{}
	for rows.Next() {
		o, err := scanOverride(rows)
		if err != nil {
			return nil, fmt.Errorf("scan surcharge override: %w", err)
		}
		out = append(out, o)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate surcharge overrides: %w", err)
	}
	return out, nil
}

// scanner is satisfied by both pgx.Row and pgx.Rows.
type scanner interface {
	Scan(dest ...any) error
}

func scanOverride(row scanner) (Override, error) {
	var o Override
	err := row.Scan(&o.ID, &o.Lane, &o.RateBps, &o.Active, &o.CreatedAt, &o.UpdatedAt)
	return o, err
}
```

