package store

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"

	"example.com/kestrel/quote/internal/db"
)

// ErrNotFound is returned when no active override exists for a lane.
var ErrNotFound = errors.New("surcharge override not found")

// SurchargeOverride is the domain type used outside the store.
type SurchargeOverride struct {
	ID             int64
	Lane           string
	SurchargeBPS   int32
	EffectiveFrom  time.Time
	EffectiveUntil *time.Time // nil means open-ended
	CreatedAt      time.Time
}

// NewSurchargeOverride is the input to Create.
type NewSurchargeOverride struct {
	Lane           string
	SurchargeBPS   int32
	EffectiveFrom  time.Time
	EffectiveUntil *time.Time
}

// querier is the subset of the sqlc-generated *db.Queries that the store uses.
// Keeping it as an interface lets tests use a small fake.
type querier interface {
	CreateSurchargeOverride(ctx context.Context, arg db.CreateSurchargeOverrideParams) (db.SurchargeOverride, error)
	GetSurchargeOverrideByLane(ctx context.Context, lane string) (db.SurchargeOverride, error)
	ListActiveSurchargeOverrides(ctx context.Context) ([]db.SurchargeOverride, error)
}

// SurchargeOverrides provides create, get-by-lane, and list-active operations.
type SurchargeOverrides struct {
	q querier
}

// NewSurchargeOverrides wraps a sqlc Queries value (db.New(pool)).
func NewSurchargeOverrides(q querier) *SurchargeOverrides {
	return &SurchargeOverrides{q: q}
}

// Create inserts a new override and returns the stored row.
func (s *SurchargeOverrides) Create(ctx context.Context, in NewSurchargeOverride) (SurchargeOverride, error) {
	if in.Lane == "" {
		return SurchargeOverride{}, errors.New("lane is required")
	}
	if in.EffectiveUntil != nil && !in.EffectiveUntil.After(in.EffectiveFrom) {
		return SurchargeOverride{}, errors.New("effective_until must be after effective_from")
	}

	row, err := s.q.CreateSurchargeOverride(ctx, db.CreateSurchargeOverrideParams{
		Lane:           in.Lane,
		SurchargeBps:   in.SurchargeBPS,
		EffectiveFrom:  timestamptz(in.EffectiveFrom),
		EffectiveUntil: timestamptzPtr(in.EffectiveUntil),
	})
	if err != nil {
		return SurchargeOverride{}, fmt.Errorf("create surcharge override: %w", err)
	}
	return fromRow(row), nil
}

// GetByLane returns the override in effect now for the lane, or ErrNotFound.
func (s *SurchargeOverrides) GetByLane(ctx context.Context, lane string) (SurchargeOverride, error) {
	row, err := s.q.GetSurchargeOverrideByLane(ctx, lane)
	if errors.Is(err, pgx.ErrNoRows) {
		return SurchargeOverride{}, ErrNotFound
	}
	if err != nil {
		return SurchargeOverride{}, fmt.Errorf("get surcharge override for lane %q: %w", lane, err)
	}
	return fromRow(row), nil
}

// ListActive returns all overrides in effect now, ordered by lane.
func (s *SurchargeOverrides) ListActive(ctx context.Context) ([]SurchargeOverride, error) {
	rows, err := s.q.ListActiveSurchargeOverrides(ctx)
	if err != nil {
		return nil, fmt.Errorf("list active surcharge overrides: %w", err)
	}
	out := make([]SurchargeOverride, 0, len(rows))
	for _, r := range rows {
		out = append(out, fromRow(r))
	}
	return out, nil
}

func fromRow(r db.SurchargeOverride) SurchargeOverride {
	o := SurchargeOverride{
		ID:            r.ID,
		Lane:          r.Lane,
		SurchargeBPS:  r.SurchargeBps,
		EffectiveFrom: r.EffectiveFrom.Time,
		CreatedAt:     r.CreatedAt.Time,
	}
	if r.EffectiveUntil.Valid {
		t := r.EffectiveUntil.Time
		o.EffectiveUntil = &t
	}
	return o
}

func timestamptz(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}

func timestamptzPtr(t *time.Time) pgtype.Timestamptz {
	if t == nil {
		return pgtype.Timestamptz{}
	}
	return timestamptz(*t)
}
```

