package surcharge

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
)

var (
	ErrNotFound = errors.New("surcharge override not found")
	ErrInvalid  = errors.New("invalid surcharge override")
)

// DBTX is satisfied by *pgxpool.Pool and pgx.Tx.
type DBTX interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

// Override is one row of surcharge_overrides.
type Override struct {
	ID              int64      `db:"id"`
	LaneOrigin      string     `db:"lane_origin"`
	LaneDestination string     `db:"lane_destination"`
	RateBps         int32      `db:"rate_bps"`
	Active          bool       `db:"active"`
	EffectiveFrom   time.Time  `db:"effective_from"`
	EffectiveUntil  *time.Time `db:"effective_until"`
	CreatedAt       time.Time  `db:"created_at"`
}

// NewOverride holds the caller-supplied fields for Create.
type NewOverride struct {
	LaneOrigin      string
	LaneDestination string
	RateBps         int32
	EffectiveFrom   time.Time  // zero means now (UTC)
	EffectiveUntil  *time.Time // nil means open-ended
}

type Store struct {
	db DBTX
}

func NewStore(db DBTX) *Store {
	return &Store{db: db}
}

const overrideColumns = `id, lane_origin, lane_destination, rate_bps, active,
	effective_from, effective_until, created_at`

const createSQL = `
INSERT INTO surcharge_overrides (lane_origin, lane_destination, rate_bps, effective_from, effective_until)
VALUES ($1, $2, $3, $4, $5)
RETURNING ` + overrideColumns

const getByLaneSQL = `
SELECT ` + overrideColumns + `
FROM surcharge_overrides
WHERE lane_origin = $1 AND lane_destination = $2 AND active
ORDER BY effective_from DESC, id DESC
LIMIT 1`

const listActiveSQL = `
SELECT ` + overrideColumns + `
FROM surcharge_overrides
WHERE active
  AND effective_from <= $1
  AND (effective_until IS NULL OR effective_until > $1)
ORDER BY lane_origin, lane_destination, effective_from DESC, id DESC`

// Create inserts an override and returns the stored row.
func (s *Store) Create(ctx context.Context, in NewOverride) (Override, error) {
	if in.EffectiveFrom.IsZero() {
		in.EffectiveFrom = time.Now().UTC()
	}
	if err := in.validate(); err != nil {
		return Override{}, err
	}
	rows, err := s.db.Query(ctx, createSQL,
		in.LaneOrigin, in.LaneDestination, in.RateBps, in.EffectiveFrom, in.EffectiveUntil)
	if err != nil {
		return Override{}, fmt.Errorf("insert surcharge override: %w", err)
	}
	o, err := pgx.CollectOneRow(rows, pgx.RowToStructByName[Override])
	if err != nil {
		return Override{}, fmt.Errorf("scan surcharge override: %w", err)
	}
	return o, nil
}

// GetByLane returns the newest active override for the lane.
func (s *Store) GetByLane(ctx context.Context, origin, destination string) (Override, error) {
	rows, err := s.db.Query(ctx, getByLaneSQL, origin, destination)
	if err != nil {
		return Override{}, fmt.Errorf("query surcharge override: %w", err)
	}
	o, err := pgx.CollectOneRow(rows, pgx.RowToStructByName[Override])
	if errors.Is(err, pgx.ErrNoRows) {
		return Override{}, ErrNotFound
	}
	if err != nil {
		return Override{}, fmt.Errorf("scan surcharge override: %w", err)
	}
	return o, nil
}

// ListActive returns overrides in force at the given instant.
func (s *Store) ListActive(ctx context.Context, at time.Time) ([]Override, error) {
	rows, err := s.db.Query(ctx, listActiveSQL, at)
	if err != nil {
		return nil, fmt.Errorf("query active surcharge overrides: %w", err)
	}
	out, err := pgx.CollectRows(rows, pgx.RowToStructByName[Override])
	if err != nil {
		return nil, fmt.Errorf("scan active surcharge overrides: %w", err)
	}
	return out, nil
}

func (n NewOverride) validate() error {
	switch {
	case n.LaneOrigin == "" || n.LaneDestination == "":
		return fmt.Errorf("%w: lane origin and destination are required", ErrInvalid)
	case n.LaneOrigin == n.LaneDestination:
		return fmt.Errorf("%w: origin and destination must differ", ErrInvalid)
	case n.RateBps < 0:
		return fmt.Errorf("%w: rate must not be negative", ErrInvalid)
	case n.EffectiveUntil != nil && !n.EffectiveUntil.After(n.EffectiveFrom):
		return fmt.Errorf("%w: effective_until must be after effective_from", ErrInvalid)
	}
	return nil
}
