func TestNewOverrideValidate(t *testing.T) {
	from := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	before := from.Add(-time.Hour)
	after := from.Add(time.Hour)

	tests := []struct {
		name    string
		in      NewOverride
		wantErr bool
	}{
		{"ok", NewOverride{LaneOrigin: "CHI", LaneDestination: "MSP", RateBps: 250, EffectiveFrom: from}, false},
		{"open-ended ok", NewOverride{LaneOrigin: "CHI", LaneDestination: "MSP", RateBps: 0, EffectiveFrom: from, EffectiveUntil: &after}, false},
		{"missing origin", NewOverride{LaneDestination: "MSP", EffectiveFrom: from}, true},
		{"same origin and destination", NewOverride{LaneOrigin: "CHI", LaneDestination: "CHI", EffectiveFrom: from}, true},
		{"negative rate", NewOverride{LaneOrigin: "CHI", LaneDestination: "MSP", RateBps: -1, EffectiveFrom: from}, true},
		{"until before from", NewOverride{LaneOrigin: "CHI", LaneDestination: "MSP", EffectiveFrom: from, EffectiveUntil: &before}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.in.validate()
			if (err != nil) != tt.wantErr {
				t.Fatalf("validate() err = %v, wantErr %v", err, tt.wantErr)
			}
			if err != nil && !errors.Is(err, ErrInvalid) {
				t.Fatalf("validate() err = %v, want ErrInvalid", err)
			}
		})
	}
}

