import (
	"context"
	"errors"
	"sync"
	"time"
)

var errLookupPanicked = errors.New("surcharge lookup panicked")

// Key identifies one cached surcharge: a lane plus a calendar day.
type Key struct {
	Lane string
	Date string // "2006-01-02", in the business-local location
}

// Surcharge is a placeholder. Replace with the type your lookup returns.
type Surcharge struct {
	Amount   int64 // minor units, e.g. cents
	Currency string
}

// LookupFunc is the uncached surcharge lookup.
type LookupFunc func(ctx context.Context, lane string, date time.Time) (Surcharge, error)

type entry[V any] struct {
	val     V
	expires time.Time
}

type call[V any] struct {
	done chan struct{}
	val  V
	err  error
}

// TTLCache is an in-process TTL cache with single-flight loading:
// concurrent misses for the same key share one upstream call.
// Errors are never cached.
type TTLCache[K comparable, V any] struct {
	ttl     time.Duration
	now     func() time.Time
	mu      sync.Mutex
	entries map[K]entry[V]
	calls   map[K]*call[V]
}

func NewTTLCache[K comparable, V any](ttl time.Duration) *TTLCache[K, V] {
	return &TTLCache[K, V]{
		ttl:     ttl,
		now:     time.Now,
		entries: make(map[K]entry[V]),
		calls:   make(map[K]*call[V]),
	}
}

// Do returns the cached value for key, or runs load once and caches a successful result.
func (c *TTLCache[K, V]) Do(ctx context.Context, key K, load func(context.Context) (V, error)) (V, error) {
	var zero V

	c.mu.Lock()
	if e, ok := c.entries[key]; ok && c.now().Before(e.expires) {
		c.mu.Unlock()
		return e.val, nil
	}
	if cl, ok := c.calls[key]; ok {
		c.mu.Unlock()
		select {
		case <-cl.done:
			return cl.val, cl.err
		case <-ctx.Done():
			return zero, ctx.Err()
		}
	}
	cl := &call[V]{done: make(chan struct{})}
	c.calls[key] = cl
	c.mu.Unlock()

	completed := false
	defer func() {
		if !completed {
			cl.err = errLookupPanicked
		}
		c.mu.Lock()
		delete(c.calls, key)
		if cl.err == nil {
			c.sweepLocked()
			c.entries[key] = entry[V]{val: cl.val, expires: c.now().Add(c.ttl)}
		}
		c.mu.Unlock()
		close(cl.done)
	}()

	cl.val, cl.err = load(ctx)
	completed = true
	return cl.val, cl.err
}

// sweepLocked drops expired entries once the map gets large, so it can't grow without bound.
// Caller must hold c.mu.
func (c *TTLCache[K, V]) sweepLocked() {
	const sweepAt = 1024
	if len(c.entries) < sweepAt {
		return
	}
	now := c.now()
	for k, e := range c.entries {
		if !now.Before(e.expires) {
			delete(c.entries, k)
		}
	}
}
