		ttl:      ttl,
		now:      time.Now,
		load:     load,
		entries:  make(map[Key]entry[V]),
		inflight: make(map[Key]*call[V]),
	}
}

func (c *Cache[V]) Get(ctx context.Context, k Key) (V, error) {
	c.mu.Lock()
	if e, ok := c.entries[k]; ok {
		if c.now().Before(e.expires) {
			c.mu.Unlock()
			return e.val, nil
		}
		delete(c.entries, k)
	}
	if cl, ok := c.inflight[k]; ok {
		c.mu.Unlock()
		select {
		case <-cl.done:
			return cl.val, cl.err
		case <-ctx.Done():
			var zero V
			return zero, ctx.Err()
		}
	}
	cl := &call[V]{done: make(chan struct{}), err: errIncomplete}
	c.inflight[k] = cl
	c.mu.Unlock()

	defer func() { // runs on panic too; errIncomplete stays set, so nothing is cached
		c.mu.Lock()
		delete(c.inflight, k)
		if cl.err == nil {
			c.store(k, cl.val)
		}
		c.mu.Unlock()
		close(cl.done)
	}()
	cl.val, cl.err = c.load(ctx, k)
	return cl.val, cl.err
}

