package surchargecache

import (
	"context"
	"sync"
	"time"
)

// Fetcher is the uncached surcharge lookup. Pass the real lookup function here.
type Fetcher[V any] func(ctx context.Context, lane string, day time.Time) (V, error)

// Key identifies one cache entry. Date is the calendar day in the lane's
// business time zone, so callers should pass a day already in that zone.
type Key struct {
	Lane string
	Date string
}

// NewKey builds a Key from a lane and a day, formatting the day as YYYY-MM-DD.
func NewKey(lane string, day time.Time) Key {
	return Key{Lane: lane, Date: day.Format(time.DateOnly)}
}

type entry[V any] struct {
	val     V
	expires time.Time
}

// flight is one in-progress fetch that concurrent callers wait on.
type flight[V any] struct {
	done chan struct{}
	val  V
	err  error
}

// Cache holds surcharge values for a fixed TTL and collapses concurrent misses.
type Cache[V any] struct {
	fetch   Fetcher[V]
	ttl     time.Duration
	now     func() time.Time
	mu      sync.Mutex
	entries map[Key]entry[V]
	flights map[Key]*flight[V]
}

// New returns a Cache that serves values for ttl after they are fetched.
func New[V any](fetch Fetcher[V], ttl time.Duration) *Cache[V] {
	return &Cache[V]{
		fetch:   fetch,
		ttl:     ttl,
		now:     time.Now,
		entries: make(map[Key]entry[V]),
		flights: make(map[Key]*flight[V]),
	}
}

// Get returns the surcharge for lane and day, calling the fetcher on a miss.
// Concurrent misses for the same key share one fetch. Errors are not cached.
func (c *Cache[V]) Get(ctx context.Context, lane string, day time.Time) (V, error) {
	k := NewKey(lane, day)

	c.mu.Lock()
	if e, ok := c.entries[k]; ok && c.now().Before(e.expires) {
		c.mu.Unlock()
		return e.val, nil
	}
	if f, ok := c.flights[k]; ok {
		c.mu.Unlock()
		select {
		case <-f.done:
			return f.val, f.err
		case <-ctx.Done():
			var zero V
			return zero, ctx.Err()
		}
	}
	f := &flight[V]{done: make(chan struct{})}
	c.flights[k] = f
	c.mu.Unlock()

	f.val, f.err = c.fetch(ctx, lane, day)

	c.mu.Lock()
	delete(c.flights, k)
	if f.err == nil {
		c.entries[k] = entry[V]{val: f.val, expires: c.now().Add(c.ttl)}
	}
	c.evictExpiredLocked()
	c.mu.Unlock()

	close(f.done)
	return f.val, f.err
}

// evictExpiredLocked drops expired entries so the map stays bounded by
// recent lanes and days. Caller must hold c.mu.
func (c *Cache[V]) evictExpiredLocked() {
	now := c.now()
	for k, e := range c.entries {
		if !now.Before(e.expires) {
			delete(c.entries, k)
		}
	}
}
