// Package surcharge puts a read-through cache in front of the surcharge lookup.
// Entries live for 60 seconds and are keyed by lane and date.
package surcharge

import (
	"context"
	"encoding/json"
	"time"
)

// DefaultTTL is how long a surcharge may be served from cache.
const DefaultTTL = 60 * time.Second

// Source is the uncached lookup, e.g. the fuel-surcharge table query.
type Source[T any] interface {
	Surcharge(ctx context.Context, lane string, date time.Time) (T, error)
}

// Store is the key-value surface the cache needs. A Valkey client adapter implements it.
type Store interface {
	Get(ctx context.Context, key string) (value []byte, found bool, err error)
	Set(ctx context.Context, key string, value []byte, ttl time.Duration) error
}

// Cache is a read-through cache around Source. Cache failures never fail a lookup.
type Cache[T any] struct {
	Source Source[T]
	Store  Store
	TTL    time.Duration // zero means DefaultTTL
	// OnError, if set, receives cache failures ("get", "decode", "encode", "set").
	// Wire it to a metric so Valkey problems are visible.
	OnError func(op string, err error)
}

// Key returns the cache key for a lane and calendar date. The date is formatted
// as YYYY-MM-DD in the location the caller passes, so callers must normalize
// to the business time zone first.
func Key(lane string, date time.Time) string {
	return "surcharge:v1:" + lane + ":" + date.Format(time.DateOnly)
}

// Surcharge returns the cached surcharge for lane and date, or fetches it from
// Source and caches the result for the TTL. Source errors are returned and not cached.
func (c *Cache[T]) Surcharge(ctx context.Context, lane string, date time.Time) (T, error) {
	var zero T
	key := Key(lane, date)

	raw, found, err := c.Store.Get(ctx, key)
	if err != nil {
		c.report("get", err)
	} else if found {
		var v T
		if err := json.Unmarshal(raw, &v); err == nil {
			return v, nil
		} else {
			c.report("decode", err) // corrupt entry: refetch and overwrite
		}
	}

	v, err := c.Source.Surcharge(ctx, lane, date)
	if err != nil {
		return zero, err
	}
	if raw, err := json.Marshal(v); err != nil {
		c.report("encode", err)
	} else if err := c.Store.Set(ctx, key, raw, c.ttl()); err != nil {
		c.report("set", err)
	}
	return v, nil
}

func (c *Cache[T]) ttl() time.Duration {
	if c.TTL <= 0 {
		return DefaultTTL
	}
	return c.TTL
}

func (c *Cache[T]) report(op string, err error) {
	if c.OnError != nil {
		c.OnError(op, err)
	}
}
