**Choices I made:**
- **In-process cache**, not Valkey. It needs no new infrastructure, and each replica can be up to 60 seconds stale.
- **Key is lane plus civil date** (`YYYY-MM-DD`). Pass the date in the timezone the surcharge is defined in.
- **Errors are not cached**, so a failed lookup retries on the next call.
- **Concurrent misses for the same key share one upstream call.**
- **Bounded size.** When full, it drops expired entries, and if still full it clears everything. That's crude but safe. Adjust if you want LRU.

```go
// surcharge/cache.go
package surcharge

import (
	"context"
	"sync"
	"time"
)

// TTL is how long a surcharge stays cached. A surcharge change can take up
// to this long to show up in quotes on any given replica.
const TTL = 60 * time.Second

// fetchTimeout bounds one upstream lookup, so a hung call can't pin an
// in-flight entry forever.
const fetchTimeout = 5 * time.Second

type key struct {
	lane string
	date string // YYYY-MM-DD
}

type entry[V any] struct {
	val     V
	expires time.Time
}

type call[V any] struct {
	done chan struct{}
	val  V
	err  error
}

// Cache wraps a surcharge lookup with a short TTL. Safe for concurrent use.
type Cache[V any] struct {
	lookup  func(ctx context.Context, lane string, date time.Time) (V, error)
	ttl     time.Duration
	maxSize int
	now     func() time.Time

	mu       sync.Mutex
	entries  map[key]entry[V]
	inflight map[key]*call[V]
}

// NewCache returns a cache that calls lookup on misses and keeps successful
// results for ttl, holding at most maxSize entries.
func NewCache[V any](lookup func(context.Context, string, time.Time) (V, error), ttl time.Duration, maxSize int) *Cache[V] {
	return &Cache[V]{
		lookup:   lookup,
		ttl:      ttl,
		maxSize:  maxSize,
		now:      time.Now,
		entries:  make(map[key]entry[V]),
		inflight: make(map[key]*call[V]),
	}
}

// Get returns the surcharge for lane on date, using the cache when fresh.
func (c *Cache[V]) Get(ctx context.Context, lane string, date time.Time) (V, error) {
	k := key{lane: lane, date: date.Format(time.DateOnly)}

	c.mu.Lock()
	if e, ok := c.entries[k]; ok && c.now().Before(e.expires) {
		c.mu.Unlock()
		return e.val, nil
	}
	if cl, ok := c.inflight[k]; ok {
		c.mu.Unlock()
		return c.wait(ctx, cl)
	}
	cl := &call[V]{done: make(chan struct{})}
	c.inflight[k] = cl
	c.mu.Unlock()

	// The fetch runs detached from this caller's cancellation, so one caller
	// giving up doesn't fail everyone else waiting on the same key.
	go c.fill(context.WithoutCancel(ctx), k, cl, lane, date)

	return c.wait(ctx, cl)
}

func (c *Cache[V]) fill(ctx context.Context, k key, cl *call[V], lane string, date time.Time) {
	ctx, cancel := context.WithTimeout(ctx, fetchTimeout)
	defer cancel()

	v, err := c.lookup(ctx, lane, date)

	c.mu.Lock()
	delete(c.inflight, k)
	if err == nil {
		c.store(k, v)
	}
	c.mu.Unlock()

	cl.val, cl.err = v, err
	close(cl.done)
}

// store must be called with c.mu held.
func (c *Cache[V]) store(k key, v V) {
	now := c.now()
	if len(c.entries) >= c.maxSize {
		for kk, e := range c.entries {
			if !now.Before(e.expires) {
				delete(c.entries, kk)
			}
		}
	}
	if len(c.entries) >= c.maxSize {
		clear(c.entries)
	}
	c.entries[k] = entry[V]{val: v, expires: now.Add(c.ttl)}
}

func (c *Cache[V]) wait(ctx context.Context, cl *call[V]) (V, error) {
	select {
	case <-cl.done:
		return cl.val, cl.err
	case <-ctx.Done():
		var zero V
		return zero, ctx.Err()
	}
}
